const $=s=>document.querySelector(s);let token=localStorage.getItem("novabank_token")||"",me=null,customersCache=[],offersCache=[],selectedCustomer=null;
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const money=c=>`N₹${(Number(c||0)/100).toLocaleString("en-IN",{minimumFractionDigits:2,maximumFractionDigits:2})}`;
function notice(msg,bad=false){const n=$("#notice");n.textContent=msg;n.classList.toggle("error",bad);n.classList.remove("hidden");setTimeout(()=>n.classList.add("hidden"),6500)}
async function api(path,opts={}){const headers={"content-type":"application/json",...(opts.headers||{})};if(token)headers.authorization="Bearer "+token;const r=await fetch("/api"+path,{...opts,headers});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||`Request failed (${r.status})`);return d}
function showApp(){ $("#loginPanel").classList.add("hidden");$("#app").classList.remove("hidden");$("#logout").classList.remove("hidden");$("#welcome").textContent=`Signed in as ${me.display_name||me.displayName||me.username} · ${me.email||""}`;}
function signOut(){token="";me=null;localStorage.removeItem("novabank_token");$("#app").classList.add("hidden");$("#loginPanel").classList.remove("hidden");$("#logout").classList.add("hidden")}
$("#loginForm").addEventListener("submit",async e=>{e.preventDefault();$("#loginError").textContent="";try{const result=await api("/login",{method:"POST",body:JSON.stringify({...Object.fromEntries(new FormData(e.target)),loginMode:"admin"})});token=result.token;me=result.user;if(me?.role!=="admin"){await api("/logout",{method:"POST",body:"{}"}).catch(()=>{});token="";throw Error("This portal is for Super Admin accounts only.")}localStorage.setItem("novabank_token",token);showApp();await refreshAll()}catch(err){$("#loginError").textContent=err.message;localStorage.removeItem("novabank_token")}});
$("#logout").addEventListener("click",signOut);
function info(label,value){return `<div class="info"><small>${esc(label)}</small><strong>${esc(value??"—")}</strong></div>`}
function card(title,lines,actions=""){return `<article class="item"><strong>${esc(title)}</strong>${lines.map(([k,v])=>`<p>${esc(k)}: <b>${esc(v??"—")}</b></p>`).join("")}${actions}</article>`}
function table(rows,cols){if(!rows?.length)return '<p class="empty">No records found.</p>';return `<table class="table"><thead><tr>${cols.map(c=>`<th>${esc(c[1])}</th>`).join("")}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${esc(typeof c[2]==="function"?c[2](r):r[c[0]])}</td>`).join("")}</tr>`).join("")}</tbody></table>`}
function goto(tab){document.querySelectorAll(".tab").forEach(b=>b.classList.toggle("active",b.dataset.tab===tab));document.querySelectorAll(".tab-pane").forEach(p=>p.classList.toggle("hidden",p.id!==`pane-${tab}`));if(tab==="money")loadMoney();if(tab==="applications"){loadApplications();loadClosureQueue();loadCardControlQueue();}if(tab==="offers")loadOffers();if(tab==="portfolio")loadPortfolio();if(tab==="ledger")loadLedger();if(tab==="treasury")loadTreasury();if(tab==="staff")loadStaff();if(tab==="payroll")loadPayroll()}
$("#tabs").addEventListener("click",e=>{const b=e.target.closest("[data-tab]");if(b)goto(b.dataset.tab)});document.body.addEventListener("click",e=>{const b=e.target.closest("[data-goto]");if(b)goto(b.dataset.goto)});
async function refreshAll(){await Promise.allSettled([loadSummary(),loadCustomers(""),loadOffers(),loadMoney(),loadApplications(),loadClosureQueue(),loadCardControlQueue(),loadPortfolio(),loadLedger(),loadTreasury()])}
async function loadSummary(){const d=await api("/admin/summary");$("#stats").innerHTML=[["Customers",d.customers],["Accounts",d.accounts],["Active loan count",d.loanCount],["Virtual cards",d.cardCount],["Customer demo balances",money(d.customerBalances)],["Loans disbursed",money(d.loanDisbursed)],["Loan outstanding",money(d.loanOutstanding)],["Card outstanding",money(d.cardOutstanding)]].map(x=>`<article><small>${esc(x[0])}</small><strong>${esc(x[1])}</strong></article>`).join("");$("#fundSnapshot").innerHTML=[info("Approved deposits",money(d.approvedDeposits)),info("Approved withdrawals",money(d.approvedWithdrawals)),info("Loans disbursed",money(d.loanDisbursed)),info("Loan principal book",money(d.loanPrincipal)),info("Loan repayments / foreclosure",money(d.loanRepaid)),info("Remaining loan outstanding",money(d.loanOutstanding)),info("Credit limits issued",money(d.cardLimits)),info("Credit-card outstanding",money(d.cardOutstanding))].join("");$("#queueSnapshot").innerHTML=[["Pending money requests",null],["Loan applications",d.pendingLoanApplications],["Card applications",d.pendingCardApplications]].map(x=>`<div class="queue-row"><strong>${x[0]}</strong><b>${x[1]??"Open queue"}</b></div>`).join("");}
async function loadCustomers(q){const d=await api(`/admin/customers${q?`?q=${encodeURIComponent(q)}`:""}`);customersCache=d.customers||[];const unique=new Map();for(const r of customersCache){if(!unique.has(r.user_id))unique.set(r.user_id,{...r,accounts:[]});if(r.account_id)unique.get(r.user_id).accounts.push(r)}const list=[...unique.values()];const sel=$("#targetUser");if(sel)sel.innerHTML=list.map(c=>`<option value="${esc(c.user_id)}">${esc(c.display_name||c.username)} · ${esc(c.accounts[0]?.account_number||"No account")}</option>`).join("");return list}
$("#searchForm").addEventListener("submit",async e=>{e.preventDefault();try{const list=await loadCustomers($("#query").value.trim());$("#customerResults").innerHTML=list.map(c=>`<div class="result-row"><div><strong>${esc(c.display_name||c.username)}</strong><small>${esc(c.username)} · ${esc(c.email)}</small><small>${esc(c.accounts.map(a=>a.account_number).join(", ")||"No account")} · ${esc(c.user_status||"unknown")}</small></div><button class="btn" data-customer="${esc(c.user_id)}">View details</button></div>`).join("")||'<p class="empty">No matching customer.</p>';$("#customerResults").querySelectorAll("[data-customer]").forEach(b=>b.addEventListener("click",()=>loadCustomer(b.dataset.customer)))}catch(e){notice(e.message,true)}});
$("#clearSearch").addEventListener("click",()=>{$("#query").value="";$("#customerResults").innerHTML='<p class="muted">Search to view customer records.</p>';$("#detailPanel").classList.add("hidden")});$("#closeDetails").addEventListener("click",()=>$("#detailPanel").classList.add("hidden"));
async function loadCustomer(id){selectedCustomer=id;try{const d=await api(`/admin/customer-details?userId=${encodeURIComponent(id)}`),c=d.customer;$("#detailPanel").classList.remove("hidden");$("#customerTitle").textContent=c.display_name||c.username;$("#customerMeta").textContent=`${c.username} · ${c.email} · ${c.created_at||""}`;$("#profileGrid").innerHTML=[info("Customer ID",c.id),info("Username",c.username),info("Email",c.email),info("Status",c.status),info("Registered",c.created_at),info("Account count",(Array.isArray(d.accounts)?d.accounts.length:0))].join("");
$("#accounts").innerHTML=(Array.isArray(d.accounts)?d.accounts:[]).map(a=>card(a.account_number,[["Type",a.account_type],["Balance",money(a.balance)],["Status",a.status],["Opened",a.opened_at]],`<div class="controls"><button class="btn ${a.status==="frozen"?"primary":"danger"}" data-freeze="${esc(a.id)}" data-status="${a.status==="frozen"?"active":"frozen"}">${a.status==="frozen"?"Unfreeze":"Freeze"}</button></div>`)).join("")||'<p class="empty">No accounts.</p>';
$("#accounts").querySelectorAll("[data-freeze]").forEach(b=>b.addEventListener("click",async()=>{const note=prompt("Reason for status change (required):");if(!note?.trim())return;try{await api(`/admin/accounts/${b.dataset.freeze}/status`,{method:"POST",body:JSON.stringify({status:b.dataset.status,note})});notice("Account status updated.");await loadCustomer(id)}catch(e){notice(e.message,true)}}));
$("#loans").innerHTML=(Array.isArray(d.loans)?d.loans:[]).map(l=>card(`Demo loan · ${l.status}`,[["Loan ID",l.id],["Principal",money(l.principal_amount)],["Outstanding",money(l.outstanding_amount)],["Monthly payment",money(l.monthly_payment)],["Tenure remaining",`${l.remaining_months}/${l.tenure_months} months`]],l.status==="active"?`<div class="controls"><button class="btn danger" data-foreclose="${esc(l.id)}" data-outstanding="${Number(l.outstanding_amount)}">Full one-time foreclosure</button></div>`:"")).join("")||'<p class="empty">No activated loans.</p>';
$("#loans").querySelectorAll("[data-foreclose]").forEach(b=>b.addEventListener("click",async()=>{if(!confirm(`Deduct full outstanding ${money(b.dataset.outstanding)} from linked demo balance and close loan?`))return;try{const r=await api(`/admin/loans/${b.dataset.foreclose}/foreclose`,{method:"POST",body:JSON.stringify({confirm:true})});notice(r.message);await loadCustomer(id);await loadSummary()}catch(e){notice(e.message,true)}}));
$("#cards").innerHTML=(Array.isArray(d.cards)?d.cards:[]).map(ca=>card(`Virtual card · ${ca.status}`,[["Card",ca.masked_number],["Limit",money(ca.credit_limit)],["Outstanding",money(ca.outstanding)],["Available",money(Math.max(0,ca.credit_limit-ca.outstanding))]])).join("")||'<p class="empty">No issued virtual cards.</p>';
$("#applications").innerHTML=[...(Array.isArray(d.loanApplications)?d.loanApplications:[]).map(a=>({k:"Loan",id:a.application_number||a.id,req:money(a.requested_amount),san:money(a.sanctioned_amount),status:a.status,note:a.admin_note})),...(Array.isArray(d.cardApplications)?d.cardApplications:[]).map(a=>({k:"Card",id:a.application_number||a.id,req:money(a.requested_limit),san:money(a.sanctioned_limit),status:a.status,note:a.admin_note}))].map(a=>card(`${a.k} application · ${a.status}`,[["ID",a.id],["Requested",a.req],["Sanctioned",a.san],["Admin note",a.note]])).join("")||'<p class="empty">No applications.</p>';
$("#transactions").innerHTML=table((Array.isArray(d.transactions)?d.transactions:[]),[["created_at","Date"],["type","Type"],["description","Description"],["amount","Amount",r=>money(r.amount)],["balance_after","Balance",r=>money(r.balance_after)]]);
const requestItems=[...(d.moneyRequests||[]).map(r=>({kind:`${r.type} request`,status:r.status,id:r.id,date:r.created_at,note:r.admin_note,amount:money(r.amount)})),...(d.closureRequests||[]).map(r=>({kind:`${r.product_type} closure`,status:r.status,id:r.id,date:r.created_at,note:r.admin_note,amount:money(r.amount_paid)})),...(d.accountClosureRequests||[]).map(r=>({kind:"account closure",status:r.status,id:r.id,date:r.created_at,note:r.admin_note,amount:"—"})),...(d.loanApplications||[]).map(r=>({kind:"loan application",status:r.status,id:r.id,date:r.created_at,note:r.admin_note,amount:money(r.requested_amount),archived:!!r.deleted_at})),...(d.cardApplications||[]).map(r=>({kind:"card application",status:r.status,id:r.id,date:r.created_at,note:r.admin_note,amount:money(r.requested_limit),archived:!!r.deleted_at}))];
$("#customerRequests").innerHTML=requestItems.map(r=>card(`${r.kind} · ${r.status}${r.archived?" · archived":""}`,[ ["Reference",r.id],["Date",r.date],["Amount",r.amount],["Admin note",r.note||"—"] ])).join("")||'<p class="empty">No customer requests recorded.</p>';
await loadOffers();$("#customerOffers").innerHTML=offersCache.map(o=>{const assigned=o.assignedUsers?.includes(id);return card(o.title,[["Category",o.category],["Visibility",assigned?"Assigned to this customer":o.global?"Global offer":"Targeted offer"],["Status",Number(o.active)?"Active":"Inactive"]],`<div class="controls"><button class="btn ${assigned?"danger":"primary"}" data-assign="${esc(o.id)}" data-assigned="${assigned}">${assigned?"Remove from customer":"Assign to customer"}</button></div>`)}).join("")||'<p class="empty">No offers created.</p>';$("#customerOffers").querySelectorAll("[data-assign]").forEach(b=>b.addEventListener("click",async()=>{try{await api(`/admin/offers/${b.dataset.assign}/assign`,{method:"POST",body:JSON.stringify({userId:id,assigned:b.dataset.assigned!=="true"})});notice("Customer offer assignment updated.");await loadCustomer(id)}catch(e){notice(e.message,true)}}));
$("#detailPanel").scrollIntoView({behavior:"smooth",block:"start"});}catch(e){notice(e.message,true)}}
async function loadMoney(){try{const d=await api("/admin/money-requests"),f=$("#moneyFilter").value,rows=d.requests||[];const list=f==="all"?rows:rows.filter(r=>r.status===f);$("#moneyRequests").innerHTML=list.map(r=>card(`${r.type==="deposit"?"Deposit":"Withdrawal"} · ${r.status}`,[["Request ID",r.id],["Customer",r.display_name||r.username],["Account",r.account_number],["Amount",money(r.amount)],["Description",r.description],["Submitted",r.created_at],["Admin note",r.admin_note]],["pending","processing"].includes(r.status)?`<div class="controls"><input data-note="${esc(r.id)}" placeholder="Reason / admin note"><button class="btn primary" data-review-money="${esc(r.id)}" data-status="approved">Approve</button><button class="btn danger" data-review-money="${esc(r.id)}" data-status="rejected">Reject</button></div>`:"")).join("")||'<p class="empty">No requests in this filter.</p>';$("#moneyRequests").querySelectorAll("[data-review-money]").forEach(b=>b.addEventListener("click",async()=>{const note=$("#moneyRequests").querySelector(`[data-note="${CSS.escape(b.dataset.reviewMoney)}"]`)?.value||"";if(!note.trim()&&!confirm("Proceed without an admin note?"))return;try{await api(`/admin/money-requests/${b.dataset.reviewMoney}/review`,{method:"POST",body:JSON.stringify({status:b.dataset.status,note})});notice("Request reviewed.");await loadMoney();await loadSummary();await loadLedger()}catch(e){notice(e.message,true)}}))}catch(e){$("#moneyRequests").innerHTML=`<p class="error">${esc(e.message)}</p>`}}
$("#moneyFilter").addEventListener("change",loadMoney);$("#refreshMoney").addEventListener("click",loadMoney);
async function loadArchivedApplications(target){
  const host=target.querySelector("[data-archive-results]");
  if(!host)return;
  host.innerHTML='<p class="muted">Loading archived applications…</p>';
  try{
    const d=await api("/admin/application-archive");
    const rows=Array.isArray(d?.applications)?d.applications:[];
    const kind=target.dataset.archiveKind;
    const filtered=rows.filter(r=>r.product_type===kind);
    host.innerHTML=filtered.map(r=>card(`${kind==="loan"?"Loan":"Card"} · ${r.status}`,[
      ["Customer",r.display_name||r.username||r.user_id],["Application No",r.application_number||r.id],["Internal ID",r.id],["Requested",money(r.amount)],["Sanctioned",r.sanctioned==null?"—":money(r.sanctioned)],["Submitted",r.created_at],["Archived",r.deleted_at],["Decision note",r.admin_note||"—"]
    ])).join("")||'<p class="empty">No archived applications.</p>';
  }catch(e){host.innerHTML=`<p class="error">${esc(e.message)}</p>`;}
}
async function loadApplications(){
  const loanHost=$("#loanQueue"),cardHost=$("#cardQueue");
  if(!loanHost||!cardHost)return;
  try{
    const [l,c]=await Promise.all([api("/loans"),api("/cards")]);
    const loanRows=Array.isArray(l?.applications)?l.applications:[];
    const cardRows=Array.isArray(c?.applications)?c.applications:[];
    loanHost.innerHTML=loanRows.map(a=>card(`Loan · ${a.status}`,[
      ["Application No",a.application_number||a.id],["Customer",a.display_name||a.username],["Requested",money(a.requested_amount)],["Tenure",`${a.tenure_months??"—"} months`],["Income",money(a.monthly_income)],["Expenses",money(a.monthly_expenses)],["Existing EMI",money(a.existing_emi)],["Processing fee (5%)",a.status==="approved"?money(a.processing_fee):"Calculated on sanction"],["File charge",a.status==="approved"?money(a.file_charge):"₹1,100 on sanction"],["Net disbursement",a.status==="approved"?money(a.net_disbursement):"After fees"],["Credit score at application",a.credit_score_snapshot||"—"],["Submitted",a.created_at]
    ],`<div class="controls"><select data-lstatus="${esc(a.id)}"><option value="need_documents">Need documents</option><option value="verified">Verified</option><option value="approved">Approve &amp; archive</option><option value="rejected">Reject &amp; archive</option></select><input data-lamount="${esc(a.id)}" type="number" min="1" placeholder="Sanction N₹"><input data-lnote="${esc(a.id)}" placeholder="Decision reason"><button class="btn primary" data-lreview="${esc(a.id)}">Save decision</button></div>`)).join("")||'<p class="empty">No active loan applications.</p>';
    cardHost.innerHTML=cardRows.map(a=>card(`Card · ${a.status}`,[
      ["Application No",a.application_number||a.id],["Customer",a.display_name||a.username],["Requested limit",money(a.requested_limit)],["Suggested limit",a.suggested_limit==null?"—":money(a.suggested_limit)],["Credit score at application",a.credit_score_snapshot||"—"],["Submitted",a.created_at]
    ],`<div class="controls"><select data-cstatus="${esc(a.id)}"><option value="need_documents">Need documents</option><option value="verified">Verified</option><option value="approved">Approve &amp; archive</option><option value="rejected">Reject &amp; archive</option></select><input data-camount="${esc(a.id)}" type="number" min="1" placeholder="Sanction limit N₹"><input data-cnote="${esc(a.id)}" placeholder="Decision reason"><button class="btn primary" data-creview="${esc(a.id)}">Save decision</button></div>`)).join("")||'<p class="empty">No active card applications.</p>';
    for(const [host,kind] of [[loanHost,"loan"],[cardHost,"card"]]){
      const details=document.createElement("details");details.className="archive-history";details.dataset.archiveKind=kind;
      details.innerHTML='<summary>Archived applications <span>View history</span></summary><div data-archive-results><p class="muted">Open to load archived applications.</p></div>';
      details.addEventListener("toggle",()=>{if(details.open)loadArchivedApplications(details)});
      host.appendChild(details);
    }
    loanHost.querySelectorAll("[data-lreview]").forEach(b=>b.addEventListener("click",async()=>{
      const id=b.dataset.lreview,status=loanHost.querySelector(`[data-lstatus="${CSS.escape(id)}"]`)?.value,amt=loanHost.querySelector(`[data-lamount="${CSS.escape(id)}"]`)?.value,note=loanHost.querySelector(`[data-lnote="${CSS.escape(id)}"]`)?.value;
      try{await api(`/admin/loans/${id}/review`,{method:"POST",body:JSON.stringify({status,sanctionedAmount:amt?Number(amt):null,note})});notice(["approved","rejected"].includes(status)?"Decision saved. Application moved to archive.":"Loan application updated.");await loadApplications();await loadSummary();if(selectedCustomer)await loadCustomer(selectedCustomer)}catch(e){notice(e.message,true)}
    }));
    cardHost.querySelectorAll("[data-creview]").forEach(b=>b.addEventListener("click",async()=>{
      const id=b.dataset.creview,status=cardHost.querySelector(`[data-cstatus="${CSS.escape(id)}"]`)?.value,amt=cardHost.querySelector(`[data-camount="${CSS.escape(id)}"]`)?.value,note=cardHost.querySelector(`[data-cnote="${CSS.escape(id)}"]`)?.value;
      try{await api(`/admin/cards/${id}/review`,{method:"POST",body:JSON.stringify({status,sanctionedLimit:amt?Number(amt):null,note})});notice(["approved","rejected"].includes(status)?"Decision saved. Application moved to archive.":"Card application updated.");await loadApplications();await loadSummary();if(selectedCustomer)await loadCustomer(selectedCustomer)}catch(e){notice(e.message,true)}
    }));
  }catch(e){
    loanHost.innerHTML=`<p class="error">${esc(e.message)}</p>`;
    cardHost.innerHTML=`<p class="error">${esc(e.message)}</p>`;
  }
}
// Search any active or archived application by number, customer name or account number.
$("#applicationSearchForm")?.addEventListener("submit",async e=>{e.preventDefault();const q=$("#applicationSearchQuery").value.trim(),box=$("#applicationSearchResults");box.innerHTML='<p class="muted">Searching applications…</p>';try{const d=await api(`/admin/application-search?q=${encodeURIComponent(q)}`),rows=d.applications||[];box.innerHTML=rows.map(a=>{const loan=a.product_type==="loan",id=a.id,status=a.status,active=!a.deleted_at&&!['approved','rejected','closed'].includes(status);return card(`${loan?"Loan":"Credit card"} · ${status}`,[ ["Application No",a.application_number||id],["Customer",`${a.display_name||a.username} · ${a.username}`],["Account",a.account_number||"—"],["Requested",money(loan?a.requested_amount:a.requested_limit)],["Sanctioned",money(loan?a.sanctioned_amount:a.sanctioned_limit)],["Processing fee",loan?money(a.processing_fee):"—"],["File charge",loan?money(a.file_charge):"—"],["Net disbursement",loan?money(a.net_disbursement):"—"],["Submitted",a.created_at],["Admin note",a.admin_note||"—"],["Archive",a.deleted_at?`Archived ${a.deleted_at}`:"Active record"]],active?`<div class="controls"><select id="search-status-${esc(id)}"><option value="need_documents">Need documents</option><option value="verified">Verified</option><option value="approved">Approve</option><option value="rejected">Reject</option></select><input id="search-amount-${esc(id)}" type="number" min="1" placeholder="Sanction amount / limit"><input id="search-note-${esc(id)}" placeholder="Decision note"><button class="btn primary" type="button" data-search-review="${esc(id)}" data-kind="${loan?"loan":"card"}">Save review</button></div>`:"")}).join("")||'<p class="empty">No matching applications found.</p>';box.querySelectorAll("[data-search-review]").forEach(b=>b.addEventListener("click",async()=>{const id=b.dataset.searchReview,kind=b.dataset.kind,status=box.querySelector(`#search-status-${CSS.escape(id)}`).value,amount=Number(box.querySelector(`#search-amount-${CSS.escape(id)}`).value||0),note=box.querySelector(`#search-note-${CSS.escape(id)}`).value||"";const payload={status,note};if(status==="approved")payload[kind==="loan"?"sanctionedAmount":"sanctionedLimit"]=amount;try{await api(`/admin/${kind==="loan"?"loans":"cards"}/${encodeURIComponent(id)}/review`,{method:"POST",body:JSON.stringify(payload)});notice("Application decision saved and customer notified.");e.target.dispatchEvent(new Event("submit"));await loadApplications();await loadSummary()}catch(err){notice(err.message,true)}}));}catch(err){box.innerHTML=`<p class="error">${esc(err.message)}</p>`;}});

// Super Admin-only manual account transaction, separate from customer money requests.
let manualAccountVerified=null;
$("#manualAccountLookup")?.addEventListener("click",async()=>{const number=$("#manualAccountNumber").value.trim().toUpperCase(),host=$("#manualAccountPreview");if(!number){notice("Enter an account number first.",true);return;}host.innerHTML='<p class="muted">Fetching customer…</p>';try{const d=await api(`/branch/account-lookup?accountNumber=${encodeURIComponent(number)}`),c=d.customer;manualAccountVerified=c.accountNumber;host.innerHTML=[info("Customer name",c.name),info("Username",c.username),info("Account number",c.accountNumber),info("Account type",c.accountType),info("Current balance",money(c.balance)),info("Account status",c.status)].join("");}catch(err){manualAccountVerified=null;host.innerHTML=`<p class="error">${esc(err.message)}</p>`;}});
$("#manualAccountNumber")?.addEventListener("input",()=>{manualAccountVerified=null;$("#manualAccountPreview").innerHTML="";});
$("#manualTransactionForm")?.addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget,data=Object.fromEntries(new FormData(form));if(manualAccountVerified!==String(data.accountNumber||"").trim().toUpperCase()){notice("Fetch and verify the customer account details before posting this operation.",true);return;}if(!confirm(`Confirm ${data.operation} of N₹${Number(data.amount).toLocaleString("en-IN",{minimumFractionDigits:2,maximumFractionDigits:2})} to account ${data.accountNumber}?`))return;const button=form.querySelector('button[type="submit"]');button.disabled=true;try{const result=await api("/admin/manual-account-transaction",{method:"POST",body:JSON.stringify(data)});$("#manualTransactionResult").innerHTML=`<p class="success">${esc(result.message)} Reference: ${esc(result.operationId)} · ${esc(result.customer)}</p>`;notice(result.message);form.reset();manualAccountVerified=null;$("#manualAccountPreview").innerHTML="";await Promise.all([loadSummary(),loadLedger(),loadTreasury()]);}catch(err){notice(err.message,true);$("#manualTransactionResult").innerHTML=`<p class="error">${esc(err.message)}</p>`;}finally{button.disabled=false;}});

$("#offerForm").elements.visibility.addEventListener("change",e=>$("#targetLabel").classList.toggle("hidden",e.target.value!=="targeted"));
$("#offerForm").addEventListener("submit",async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const target=d.userId;delete d.visibility;delete d.userId;d.active=true;try{const r=await api("/admin/offers",{method:"POST",body:JSON.stringify(d)});if(target&&$("#offerForm").elements.visibility.value==="targeted")await api(`/admin/offers/${r.id}/assign`,{method:"POST",body:JSON.stringify({userId:target,assigned:true})});notice("Offer created and configured.");e.target.reset();$("#targetLabel").classList.add("hidden");await loadOffers();if(selectedCustomer)await loadCustomer(selectedCustomer)}catch(e){notice(e.message,true)}});
$("#refreshOffers").addEventListener("click",loadOffers);
async function loadOffers(){try{const d=await api("/offers");offersCache=d.offers||[];const list=await api("/admin/customers");const ids=[...new Set((list.customers||[]).map(x=>x.user_id))];for(const o of offersCache){const a=await api(`/admin/offers/${o.id}/assignments`).catch(()=>({users:[]}));o.assignedUsers=(a.users||[]).map(x=>x.user_id);o.global=o.assignedUsers.length===0;}$("#offersList").innerHTML=offersCache.map(o=>card(o.title,[["Category",o.category],["Benefit",o.benefit],["Audience",o.global?"All customers":`${o.assignedUsers.length} assigned customer(s)`],["Validity",o.valid_until||"No expiry"],["Status",Number(o.active)?"Active":"Inactive"]],`<div class="controls"><button class="btn ${Number(o.active)?"danger":"primary"}" data-offertoggle="${esc(o.id)}" data-active="${Number(o.active)?0:1}">${Number(o.active)?"Deactivate":"Activate"}</button><button class="btn danger" data-offerdelete="${esc(o.id)}">Delete</button></div>`)).join("")||'<p class="empty">No offers.</p>';$("#offersList").querySelectorAll("[data-offertoggle]").forEach(b=>b.addEventListener("click",async()=>{try{await api(`/admin/offers/${b.dataset.offertoggle}`,{method:"PATCH",body:JSON.stringify({active:b.dataset.active==="1"})});notice("Offer status updated.");await loadOffers()}catch(e){notice(e.message,true)}}));$("#offersList").querySelectorAll("[data-offerdelete]").forEach(b=>b.addEventListener("click",async()=>{if(!confirm("Remove this offer from active catalogue? Audit history will be retained."))return;try{await api(`/admin/offers/${b.dataset.offerdelete}`,{method:"DELETE",body:JSON.stringify({note:"Removed by admin"})});notice("Offer archived; history retained.");await loadOffers()}catch(e){notice(e.message,true)}}))}catch(e){$("#offersList").innerHTML=`<p class="error">${esc(e.message)}</p>`}}
async function loadPortfolio(){try{const d=await api("/products");$("#allLoans").innerHTML=(d.loans||[]).map(l=>card(`Loan · ${l.status}`,[["Customer ID",l.user_id],["Loan Account Number",l.loan_number||"Not assigned"],["Principal",money(l.principal_amount)],["Outstanding",money(l.outstanding_amount)],["Tenure remaining",`${l.remaining_months}/${l.tenure_months}`]])).join("")||'<p class="empty">No loans.</p>';$("#allCards").innerHTML=(d.cards||[]).map(c=>card(`Card · ${c.status}`,[["Customer ID",c.user_id],["Masked card",c.masked_number],["Limit",money(c.credit_limit)],["Outstanding",money(c.outstanding)]])).join("")||'<p class="empty">No cards.</p>'}catch(e){notice(e.message,true)}}
async function loadLedger(){try{const [t,a]=await Promise.all([api("/transactions"),api("/admin/audit")]);$("#ledgerTable").innerHTML=table(t.transactions,[["created_at","Date"],["account_number","Account"],["type","Type"],["description","Description"],["amount","Amount",r=>money(r.amount)],["balance_after","Balance after",r=>money(r.balance_after)]]);$("#auditTable").innerHTML=table(a.events,[["created_at","Date"],["actor_user_id","Actor"],["action","Action"],["entity_type","Entity"],["entity_id","Record"],["details_json","Details"]])}catch(e){$("#ledgerTable").innerHTML=`<p class="error">${esc(e.message)}</p>`}}
$("#refreshLedger").addEventListener("click",loadLedger);$("#refreshAudit").addEventListener("click",loadLedger);

const STAFF_PERMS=[['customer_lookup','Customer lookup'],['cash_operations','Cash deposit & withdrawal'],['loan_collection','Loan EMI collection'],['card_collection','Credit-card collection'],['loan_review','Loan application review'],['card_review','Card application review'],['money_requests','Deposit / withdrawal requests'],['audit_view','Audit & transaction read-only']];
async function loadStaff(){try{const d=await api('/admin/staff');const branches=d.branches||[];const sel=$('#staffBranch');if(sel)sel.innerHTML=branches.map(b=>`<option value="${esc(b.id)}">${esc(b.name)} (${esc(b.id)})</option>`).join('');const rows=d.staff||[];$('#staffList').innerHTML=rows.map(r=>{let ps=[];try{ps=JSON.parse(r.permissions_json||'[]')}catch{};return `<article class="item"><strong>${esc(r.display_name)} · ${esc(r.username)}</strong><p>${esc(r.email)} · ${esc(r.role_name)} · ${esc(r.branch_id||'NB-HQ')}</p><p>Status: ${Number(r.is_active)?'Active':'Disabled'}</p><div class="permission-grid">${STAFF_PERMS.map(([k,l])=>`<label class="permission-option"><input type="checkbox" data-staffperm="${esc(r.id)}" value="${k}" ${ps.includes(k)?'checked':''}><span>${l}</span></label>`).join('')}</div><div class="controls"><button class="btn primary" data-save-staff="${esc(r.id)}">Save permissions</button><button class="btn ${Number(r.is_active)?'danger':'ghost'}" data-toggle-staff="${esc(r.id)}" data-active="${Number(r.is_active)?0:1}">${Number(r.is_active)?'Disable access':'Enable access'}</button></div></article>`}).join('')||'<p class="empty">No staff accounts yet.</p>';$('#staffList').querySelectorAll('[data-save-staff]').forEach(b=>b.addEventListener('click',async()=>{const id=b.dataset.saveStaff,permissions=[...$('#staffList').querySelectorAll(`[data-staffperm="${CSS.escape(id)}"]:checked`)].map(x=>x.value);try{await api(`/admin/staff/${id}`,{method:'PATCH',body:JSON.stringify({permissions})});notice('Staff permissions saved. Existing sessions remain subject to server-side permission checks.');await loadStaff()}catch(e){notice(e.message,true)}}));$('#staffList').querySelectorAll('[data-toggle-staff]').forEach(b=>b.addEventListener('click',async()=>{const id=b.dataset.toggleStaff;const r=rows.find(x=>x.id===id);let permissions=[];try{permissions=JSON.parse(r.permissions_json||'[]')}catch{};try{await api(`/admin/staff/${id}`,{method:'PATCH',body:JSON.stringify({active:b.dataset.active==='1',permissions})});notice('Staff access status updated.');await loadStaff()}catch(e){notice(e.message,true)}}));}catch(e){$('#staffList').innerHTML=`<p class="error">${esc(e.message)}</p>`}}
const permissionPresets={cashier:['customer_lookup','cash_operations','loan_collection','card_collection'],loan_officer:['customer_lookup','loan_collection','loan_review'],credit_officer:['customer_lookup','card_collection','card_review'],auditor:['customer_lookup','audit_view'],branch_manager:['customer_lookup','cash_operations','loan_collection','card_collection','loan_review','card_review','money_requests','audit_view']};
