$('#branchForm')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('/admin/branches',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});notice('Branch created.');e.currentTarget.reset();await loadStaff()}catch(err){notice(err.message,true)}});
