let treasuryCache={transactions:[],breakdown:[]};
const TREASURY_TYPES={
 loanRevenue:['loan_processing_fee','loan_file_charge','loan_interest_revenue'],
 cardRevenue:['card_joining_fee','card_annual_fee','credit_card_transfer_fee','card_late_fee'],
 otherRevenue:['merchant_commission','subscription_revenue','service_fee'],
 capital:['opening_balance','manual_funding'],
 loans:['loan_disbursement','loan_repayment','loan_foreclosure_pending','foreclosure_reversal','admin_foreclosure'],
 cards:['card_bill_payment','card_repayment','card_purchase','credit_card_funded_transfer'],
 deposits:['customer_deposit','customer_withdrawal','admin_manual_deposit','admin_manual_withdrawal','branch_cash_deposit','branch_cash_withdrawal'],
 payroll:['payroll_salary_payment','salary_payment','payroll_bonus','staff_advance','operating_expense','business_expense'],
 transfers:['internal_transfer','internal_transfer_in','internal_transfer_out']
};
const treasuryKnownTypes=[...new Set(Object.values(TREASURY_TYPES).flat())];
const treasuryLabels={loanRevenue:'Loan Revenue',cardRevenue:'Card Revenue',otherRevenue:'Other Revenue',capital:'Capital & Funding',loans:'Loan Portfolio',cards:'Card Collections',deposits:'Customer Deposits & Withdrawals',payroll:'Payroll & Expenses',transfers:'Internal Transfers'};
function treasurySum(types){return treasuryCache.breakdown.filter(x=>types.includes(x.type)).reduce((n,x)=>n+Number(x.amount||0),0)}
function treasuryEntries(types){return treasuryCache.transactions.filter(x=>types.includes(x.type))}
function treasuryOtherEntries(){return treasuryCache.transactions.filter(x=>!treasuryKnownTypes.includes(x.type))}
function treasuryOtherTotal(){return treasuryCache.breakdown.filter(x=>!treasuryKnownTypes.includes(x.type)).reduce((n,x)=>n+Number(x.amount||0),0)}
function treasuryDateMatch(row,period){if(period==='all')return true;const d=new Date(String(row.created_at||'').replace(' ','T')+'Z');if(Number.isNaN(d.getTime()))return true;const now=new Date();if(period==='today')return d.toDateString()===now.toDateString();return (now-d)<=Number(period)*86400000}
function treasuryFilteredRows(){const q=($('#treasurySearch')?.value||'').trim().toLowerCase(),period=$('#treasuryPeriod')?.value||'all';return treasuryCache.transactions.filter(r=>treasuryDateMatch(r,period)&&(!q||[r.type,r.description,r.reference,r.source_type,r.source_id].some(v=>String(v||'').toLowerCase().includes(q))))}
function renderTreasuryTable(){const rows=treasuryFilteredRows();$('#treasuryTable').innerHTML=table(rows,[['created_at','Date'],['type','Type'],['description','Remarks'],['amount','Signed amount',r=>money(r.amount)],['balance_after','Ledger balance',r=>money(r.balance_after)],['reference','Unique reference'],['source_type','Source']]);$('#treasuryLedgerCount').textContent=`Showing ${rows.length} of ${treasuryCache.transactions.length} most recent ledger entries (maximum 500 returned by the API).`}
function renderTreasuryDetails(key){const ids=key==='loanRevenue'?TREASURY_TYPES.loanRevenue:key==='cardRevenue'?TREASURY_TYPES.cardRevenue:key==='otherRevenue'?TREASURY_TYPES.otherRevenue:TREASURY_TYPES[key]||[];const rows=key==='other'?treasuryOtherEntries():treasuryEntries(ids);const target=['loanRevenue','cardRevenue','otherRevenue'].includes(key)?$('#treasuryRevenueDetails'):$('#treasuryCategoryDetails');if(!rows.length){target.innerHTML=`<div class="treasury-detail-head"><h3>${esc(treasuryLabels[key])}</h3><button class="btn ghost" data-close-treasury>Close</button></div><p class="empty">No matching ledger entries in the returned history.</p>`;}else{target.innerHTML=`<div class="treasury-detail-head"><div><p class="eyebrow">CATEGORY DETAIL</p><h3>${esc(treasuryLabels[key])}</h3><small>${rows.length} ledger entries · ${esc(money(rows.reduce((n,r)=>n+Number(r.amount||0),0)))}</small></div><button class="btn ghost" data-close-treasury>Close</button></div>${table(rows,[['created_at','Date'],['type','Type'],['description','Remarks'],['amount','Amount',r=>money(r.amount)],['reference','Reference']])}`;}target.classList.remove('hidden');target.scrollIntoView({behavior:'smooth',block:'nearest'});}
async function loadTreasury(){try{const d=await api('/admin/treasury'),a=d.account||{},t=d.totals||{};treasuryCache={transactions:Array.isArray(d.transactions)?d.transactions:[],breakdown:Array.isArray(d.breakdown)?d.breakdown:[]};$('#treasuryAvailable').textContent=money(a.current_balance);$('#treasuryStats').innerHTML=[['TOTAL INFLOW',money(t.inflow),'inflow'],['TOTAL OUTFLOW',money(t.outflow),'outflow'],['BUSINESS REVENUE',money(t.revenue),'revenue'],['LEDGER ENTRIES',Number(t.entries||0).toLocaleString('en-IN'),'entries']].map(x=>`<article class="treasury-kpi ${x[2]}"><small>${esc(x[0])}</small><strong>${esc(x[1])}</strong></article>`).join('');
const loanRev=treasurySum(TREASURY_TYPES.loanRevenue),cardRev=treasurySum(TREASURY_TYPES.cardRevenue),otherRev=treasurySum(TREASURY_TYPES.otherRevenue);$('#treasuryLoanRevenue').textContent=money(loanRev);$('#treasuryCardRevenue').textContent=money(cardRev);$('#treasuryOtherRevenue').textContent=money(otherRev);$('#treasuryRevenueTotal').textContent=money(t.revenue);
const otherOps=treasuryOtherTotal();$('#treasuryOtherOps').textContent=money(otherOps);const cap=treasurySum(TREASURY_TYPES.capital),loanDisbursed=Math.abs(treasurySum(['loan_disbursement'])),cardCollections=treasurySum(['card_bill_payment','card_repayment']),depositNet=treasurySum(TREASURY_TYPES.deposits),payrollNet=treasurySum(TREASURY_TYPES.payroll),transferNet=treasurySum(TREASURY_TYPES.transfers);
$('#treasuryCapital').textContent=money(cap);$('#treasuryLoans').textContent=money(loanDisbursed);$('#treasuryCards').textContent=money(cardCollections);$('#treasuryDeposits').textContent=money(depositNet);$('#treasuryPayroll').textContent=money(Math.abs(payrollNet));$('#treasuryTransfers').textContent=money(transferNet);
$('#treasuryAccount').innerHTML=[info('Treasury account',a.name),info('Account number',a.account_number),info('Account reference',a.id)].join('');renderTreasuryTable();const opening=$('#treasuryFundingForm')?.querySelector('option[value="opening_balance"]');if(opening)opening.disabled=treasuryCache.transactions.some(r=>r.type==='opening_balance');$('#treasuryRevenueDetails').classList.add('hidden');$('#treasuryCategoryDetails').classList.add('hidden');
}catch(e){$('#treasuryTable').innerHTML=`<p class="error">${esc(e.message)}</p>`;notice(`Treasury could not be refreshed: ${e.message}`,true)}}
$('#refreshTreasury')?.addEventListener('click',loadTreasury);
$('#treasurySearch')?.addEventListener('input',renderTreasuryTable);$('#treasuryPeriod')?.addEventListener('change',renderTreasuryTable);
document.addEventListener('click',e=>{const detail=e.target.closest('[data-treasury-detail]');if(detail)renderTreasuryDetails(detail.dataset.treasuryDetail);if(e.target.closest('[data-close-treasury]')){e.target.closest('.treasury-detail-panel')?.classList.add('hidden')}});
$('#treasuryFundingForm')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=$('#treasuryFundSubmit'),data=Object.fromEntries(new FormData(form));if(!confirm(`${data.kind==='opening_balance'?'Record the one-time Opening Balance':'Add Admin Manual Funding'} of N₹${Number(data.amount).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})} to the fictional Treasury?`))return;button.disabled=true;button.textContent='Recording…';try{const result=await api('/admin/treasury/fund',{method:'POST',body:JSON.stringify(data)});notice(`${result.message} New balance: ${money(result.balance)}.`);form.reset();await Promise.all([loadTreasury(),loadSummary()]);}catch(err){notice(err.message,true)}finally{button.disabled=false;button.textContent='Record funding'}});
async function loadClosureQueue(){try{const d=await api("/closure-requests"),rows=d.requests||[];$("#closureQueue").innerHTML=rows.map(r=>card(`${r.product_type} closure · ${r.status}`,[ ["Customer",r.display_name||r.username],["Product ID",r.product_id],["Amount paid",money(r.amount_paid)],["Submitted",r.created_at],["Note",r.note],["Admin note",r.admin_note] ],r.status==="pending"?`<div class="controls"><input data-closure-note="${esc(r.id)}" placeholder="Admin note / rejection reason"><button class="btn primary" data-closure-review="${esc(r.id)}" data-status="approved">Approve & close</button><button class="btn danger" data-closure-review="${esc(r.id)}" data-status="rejected">Reject & reverse payment</button></div>`:"")).join("")||'<p class="empty">No product closure requests.</p>';$("#closureQueue").querySelectorAll("[data-closure-review]").forEach(b=>b.addEventListener("click",async()=>{const id=b.dataset.closureReview,status=b.dataset.status,note=$("#closureQueue").querySelector(`[data-closure-note="${CSS.escape(id)}"]`)?.value||"";if(!confirm(status==="approved"?"Approve this request and close the product?":"Reject this request and reverse the pending foreclosure payment if applicable?"))return;b.disabled=true;b.textContent="Processing…";try{const result=await api(`/admin/closure-requests/${id}/review`,{method:"POST",body:JSON.stringify({status,note})});notice(result.message||`Closure request ${status}.`);await Promise.all([loadClosureQueue(),loadPortfolio(),loadSummary()]);if(selectedCustomer)await loadCustomer(selectedCustomer)}catch(e){notice(e.message,true);b.disabled=false;b.textContent=status==="approved"?"Approve & close":"Reject & reverse payment"}}))}catch(e){$("#closureQueue").innerHTML=`<p class="error">${esc(e.message)}</p>`}}
async function loadCardControlQueue(){try{const d=await api("/admin/card-control-requests"),rows=d.requests||[];$("#cardControlQueue").innerHTML=rows.map(r=>card(`Card ${r.action} · ${r.status}`,[ ["Customer",r.display_name],["Username",r.username],["Card",r.masked_number],["Outstanding",money(r.outstanding)],["Submitted",r.created_at],["Note",r.note] ],r.status==="pending"?`<div class="controls"><input data-control-note="${esc(r.id)}" placeholder="Admin note"><button class="btn primary" data-control-review="${esc(r.id)}" data-status="approved">Approve</button><button class="btn danger" data-control-review="${esc(r.id)}" data-status="rejected">Reject</button></div>`:"")).join("")||'<p class="empty">No card control requests.</p>';$("#cardControlQueue").querySelectorAll("[data-control-review]").forEach(b=>b.addEventListener("click",async()=>{const id=b.dataset.controlReview,status=b.dataset.status,note=$("#cardControlQueue").querySelector(`[data-control-note="${CSS.escape(id)}"]`)?.value||"";try{await api(`/admin/card-control-requests/${id}/review`,{method:"POST",body:JSON.stringify({status,note})});notice(`Card control request ${status}.`);await loadCardControlQueue();await loadPortfolio()}catch(e){notice(e.message,true)}}))}catch(e){$("#cardControlQueue").innerHTML=`<p class="error">${esc(e.message)}</p>`}}


// NovaBank v8.1.0 HR & Payroll Control Centre
function printPayslip(s){const x=s.snapshot||{};const amt=n=>money(n);const html=`<!doctype html><html><head><meta charset="utf-8"><title>${esc(s.payslip_number||'NovaBank Payslip')}</title><style>@page{size:A4;margin:16mm}*{box-sizing:border-box}body{font:14px Arial,sans-serif;color:#172b3a;margin:0;background:#fff}.sheet{border:1px solid #d8e1e8;padding:30px;max-width:780px;margin:20px auto}.brand{display:flex;justify-content:space-between;border-bottom:3px solid #153c50;padding-bottom:18px}.brand h1{margin:0;color:#12384d;letter-spacing:2px}.muted{color:#657786;font-size:11px;letter-spacing:1px}.tag{border:1px solid #18845f;color:#18845f;padding:7px 12px;border-radius:4px;font-weight:bold}.title{margin:26px 0 4px;font-size:22px}.period{color:#607484}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:24px 0}.field small{display:block;color:#71818e;margin-bottom:5px}.field b{font-size:13px}.section{background:#f0f4f7;padding:10px 12px;font-weight:bold;margin-top:18px}table{width:100%;border-collapse:collapse}td{padding:10px 8px;border-bottom:1px solid #e1e7ec}td:last-child{text-align:right;font-weight:bold}.total{display:flex;justify-content:space-between;background:#eaf5f1;padding:18px;margin-top:18px;color:#0c684a;font-weight:bold;font-size:20px}.foot{border-top:1px solid #d8e1e8;margin-top:30px;padding-top:14px;font-size:10px;color:#687987;display:flex;justify-content:space-between}@media print{body{background:#fff}.sheet{border:0;margin:0;padding:0}}</style></head><body><main class="sheet"><header class="brand"><div><h1>NOVABANK</h1><div class="muted">HUMAN RESOURCES · PAYROLL</div></div><div class="tag">SALARY PAID</div></header><h2 class="title">Salary Slip</h2><div class="period">${esc(x.periodStart||'')} to ${esc(x.periodEnd||'')}</div><section class="grid">${[['Employee name',x.employeeName],['Employee ID',x.employeeNumber],['Designation',x.designation],['Department',x.department],['Account number',x.accountNumber],['Payment date',x.paidAt?new Date(x.paidAt).toLocaleDateString('en-IN'):'—']].map(([a,b])=>`<div class="field"><small>${esc(a)}</small><b>${esc(b||'—')}</b></div>`).join('')}</section><div class="section">Earnings</div><table><tr><td>Basic salary</td><td>${amt(x.basicSalary)}</td></tr><tr><td>Bonus / Incentive</td><td>${amt(x.bonus)}</td></tr><tr><td>Gross earnings</td><td>${amt(Number(x.basicSalary||0)+Number(x.bonus||0))}</td></tr></table><div class="section">Deductions</div><table><tr><td>Other deductions</td><td>${amt(x.deductions)}</td></tr><tr><td>Salary advance adjustment</td><td>${amt(x.advanceAdjustment)}</td></tr></table><div class="total"><span>NET SALARY PAID</span><span>${amt(x.netSalary)}</span></div><p>Payment mode: <b>${esc(x.paymentMethod==='internal'?'NovaBank account transfer':'Manual / external payment')}</b> &nbsp; Reference: <b>${esc(x.paymentReference||'—')}</b></p><footer class="foot"><span>Payslip ID: ${esc(s.payslip_number||'')}</span><span>Generated by NovaBank HR & Payroll</span></footer><p class="muted" style="margin-top:20px">NOVABANK DEMO BANKING SIMULATOR – NOT A REAL FINANCIAL INSTRUMENT.</p></main><script>window.onload=()=>setTimeout(()=>window.print(),300)</script></body></html>`;const w=window.open('','_blank');if(!w){notice('Allow pop-ups to print or save the payslip.',true);return;}w.document.write(html);w.document.close()}
async function loadPayroll(){try{const d=await api('/admin/payroll');
 $('#payrollEmployees').innerHTML=(d.employees||[]).map(e=>card(`${e.employee_number} · ${e.display_name}`,[['Username',e.username],['Designation',e.designation],['Department',e.department||'—'],['Linked account',e.account_number],['Frequency',e.frequency],['Basic salary',money(e.basic_salary)],['Bonus / deductions',`${money(e.default_bonus)} / ${money(e.default_deductions)}`],['Status',e.archived_at?'Archived':e.status]],`<div class="controls">${e.archived_at||e.status==='inactive'?`<button class="btn primary" data-employee-restore="${esc(e.id)}">Restore employee</button>`:`<button class="btn ghost" data-employee-compensation="${esc(e.id)}" data-basic="${Number(e.basic_salary)/100}" data-bonus="${Number(e.default_bonus)/100}" data-deductions="${Number(e.default_deductions)/100}">Update salary / incentive</button><button class="btn danger" data-employee-archive="${esc(e.id)}">Archive employee</button>`}</div>`)).join('')||'<p class="empty">No employees registered.</p>';
 $('#payrollCompHistory').innerHTML=(d.compensation||[]).map(h=>card(`${h.employee_number} · ${h.display_name}`,[['Effective date',h.effective_date],['Basic salary',money(h.basic_salary)],['Recurring incentive',money(h.default_bonus)],['Recurring deductions',money(h.default_deductions)],['Reason',h.reason],['Recorded',h.created_at]])).join('')||'<p class="empty">No salary revisions recorded yet.</p>';
 $('#payrollBatches').innerHTML=(d.batches||[]).map(b=>card(`${b.batch_number} · ${b.status}`,[['Period',`${b.period_start} to ${b.period_end}`],['Frequency',b.frequency],['Employees',b.employee_count],['Total',money(b.total_amount)],['Created',b.created_at]],b.status==='draft'?`<div class="controls"><button class="btn ghost" data-payroll-details="${esc(b.id)}">Review payment methods</button><button class="btn primary" data-payroll-approve="${esc(b.id)}">Approve & execute</button><button class="btn danger" data-payroll-reject="${esc(b.id)}">Reject batch</button></div><div id="payroll-items-${esc(b.id)}"></div>`:'')).join('')||'<p class="empty">No payroll batches yet.</p>';
 $('#payrollAdvances').innerHTML=(d.advances||[]).map(a=>card(`${a.employee_number} · ${a.display_name}`,[['Requested',money(a.requested_amount||a.amount)],['Outstanding',money(a.outstanding)],['Monthly adjustment',money(a.installment_amount)],['Reason',a.note],['Status',a.status]],a.status==='pending'?`<div class="controls"><button class="btn primary" data-advance-approve="${esc(a.id)}">Approve & credit</button><button class="btn danger" data-advance-reject="${esc(a.id)}">Reject</button></div>`:'')).join('')||'<p class="empty">No salary advance requests.</p>';
 $('#payrollPayslips').innerHTML=(d.payslips||[]).map(x=>card(`${x.payslip_number} · ${x.display_name}`,[['Employee ID',x.employee_number],['Generated',x.created_at]],`<button class="btn ghost" data-print-slip="${esc(x.id)}">Print / Save PDF</button>`)).join('')||'<p class="empty">No payslips generated yet. Payslips appear after payroll is paid.</p>';
 $('#payrollEmployees').querySelectorAll('[data-employee-archive],[data-employee-restore]').forEach(b=>b.addEventListener('click',async()=>{const action=b.hasAttribute('data-employee-archive')?'archive':'restore',id=b.dataset.employeeArchive||b.dataset.employeeRestore;if(action==='archive'&&!confirm('Archive this employee? Their financial, payslip and advance history will be retained.'))return;try{const r=await api(`/admin/payroll/employees/${id}/${action}`,{method:'POST',body:'{}'});notice(r.message);await loadPayroll()}catch(e){notice(e.message,true)}}));
 $('#payrollEmployees').querySelectorAll('[data-employee-compensation]').forEach(b=>b.addEventListener('click',async()=>{
   const basic=prompt('New basic salary (NVR):',b.dataset.basic);if(basic===null)return;
   const bonus=prompt('Recurring default incentive / bonus (NVR):',b.dataset.bonus);if(bonus===null)return;
   const deductions=prompt('Recurring default deductions (NVR):',b.dataset.deductions);if(deductions===null)return;
   const effectiveDate=prompt('Effective date (YYYY-MM-DD):',new Date().toISOString().slice(0,10));if(!effectiveDate)return;
   const reason=prompt('Reason for salary structure change (required):','Annual / performance revision');if(!reason?.trim())return;
   if(!confirm(`Save new salary structure?\nBasic: ${basic} NVR\nRecurring incentive: ${bonus} NVR\nRecurring deductions: ${deductions} NVR\nEffective: ${effectiveDate}`))return;
   try{const r=await api(`/admin/payroll/employees/${b.dataset.employeeCompensation}/compensation`,{method:'POST',body:JSON.stringify({basicSalary:basic,defaultBonus:bonus,defaultDeductions:deductions,effectiveDate,reason})});notice(r.message);await loadPayroll()}catch(e){notice(e.message,true)}
 }));
 $('#payrollAdvances').querySelectorAll('[data-advance-approve],[data-advance-reject]').forEach(b=>b.addEventListener('click',async()=>{const action=b.hasAttribute('data-advance-approve')?'approve':'reject',id=b.dataset.advanceApprove||b.dataset.advanceReject;if(action==='approve'&&!confirm('Approve and credit this salary advance to the employee linked account?'))return;const note=action==='reject'?(prompt('Reason for rejection (optional):')||''):'';try{const r=await api(`/admin/payroll/advances/${id}/${action}`,{method:'POST',body:JSON.stringify({note})});notice(r.message);await loadPayroll();await loadTreasury()}catch(e){notice(e.message,true)}}));
 $('#payrollPayslips').querySelectorAll('[data-print-slip]').forEach(b=>b.addEventListener('click',async()=>{try{const r=await api(`/admin/payroll/payslips/${b.dataset.printSlip}`);printPayslip(r.payslip)}catch(e){notice(e.message,true)}}));
 $('#payrollBatches').querySelectorAll('[data-payroll-details]').forEach(b=>b.addEventListener('click',async()=>{const host=$(`#payroll-items-${CSS.escape(b.dataset.payrollDetails)}`);try{const detail=await api(`/admin/payroll/batches/${b.dataset.payrollDetails}`);host.innerHTML=(detail.items||[]).map(i=>`<div class="item"><strong>${esc(i.employee_number)} · ${esc(i.display_name)}</strong><p>Basic: <b>${money(i.basic_salary)}</b> · Net salary: <b>${money(i.net_salary)}</b> · Advance adjustment: <b>${money(i.advance_adjustment)}</b> · Linked account: ${esc(i.account_number)}</p><div class="controls"><label>One-time incentive (NVR)<input type="number" min="0" step="0.01" data-item-bonus="${esc(i.id)}" value="${(Number(i.bonus)/100).toFixed(2)}"></label><label>Period deduction (NVR)<input type="number" min="0" step="0.01" data-item-deductions="${esc(i.id)}" value="${(Number(i.deductions)/100).toFixed(2)}"></label><button class="btn ghost" data-save-item-amounts="${esc(i.id)}">Save incentive / deduction</button><select data-paymethod="${esc(i.id)}"><option value="internal" ${i.payment_method==='internal'?'selected':''}>NovaBank account transfer</option><option value="manual" ${i.payment_method==='manual'?'selected':''}>Manual / external payment</option></select><input data-payref="${esc(i.id)}" placeholder="External reference / proof note" value="${esc(i.payment_reference||'')}"><button class="btn ghost" data-save-paymethod="${esc(i.id)}">Save method</button></div></div>`).join('');host.querySelectorAll('[data-save-item-amounts]').forEach(save=>save.addEventListener('click',async()=>{const id=save.dataset.saveItemAmounts;try{const r=await api(`/admin/payroll/items/${id}`,{method:'PATCH',body:JSON.stringify({bonus:host.querySelector(`[data-item-bonus="${CSS.escape(id)}"]`).value,deductions:host.querySelector(`[data-item-deductions="${CSS.escape(id)}"]`).value})});notice(`Incentive / deduction saved. Updated batch total: ${money(r.batchTotal)}.`);await loadPayroll()}catch(e){notice(e.message,true)}}));host.querySelectorAll('[data-save-paymethod]').forEach(save=>save.addEventListener('click',async()=>{const id=save.dataset.savePaymethod;try{await api(`/admin/payroll/items/${id}`,{method:'PATCH',body:JSON.stringify({paymentMethod:host.querySelector(`[data-paymethod="${CSS.escape(id)}"]`).value,reference:host.querySelector(`[data-payref="${CSS.escape(id)}"]`).value})});notice('Payroll payment method saved.')}catch(e){notice(e.message,true)}}));}catch(e){notice(e.message,true)}}));
 $('#payrollBatches').querySelectorAll('[data-payroll-approve]').forEach(b=>b.addEventListener('click',async()=>{if(b.disabled)return;if(!confirm('Approve this draft and execute payroll payments? Payslips will be generated.'))return;const original=b.textContent;b.disabled=true;b.textContent='Processing…';try{const r=await api(`/admin/payroll/batches/${b.dataset.payrollApprove}/approve`,{method:'POST',body:'{}'});notice(r.message);await loadPayroll();await loadTreasury()}catch(e){notice(e.message,true);b.disabled=false;b.textContent=original}}));
 $('#payrollBatches').querySelectorAll('[data-payroll-reject]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Reject this draft payroll batch? No payments will be made.'))return;try{const r=await api(`/admin/payroll/batches/${b.dataset.payrollReject}/reject`,{method:'POST',body:JSON.stringify({note:'Rejected by Super Admin'})});notice(r.message);await loadPayroll()}catch(e){notice(e.message,true)}}));
 }catch(e){$('#payrollEmployees').innerHTML=`<p class="error">${esc(e.message)}</p>`}}
$('#payrollEmployeeForm')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{const r=await api('/admin/payroll/employees',{method:'POST',body:JSON.stringify(d)});notice(r.message);e.currentTarget.reset();await loadPayroll()}catch(err){notice(err.message,true)}});
$('#payrollBatchForm')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{const r=await api('/admin/payroll/batches',{method:'POST',body:JSON.stringify(d)});notice(r.message);await loadPayroll()}catch(err){notice(err.message,true)}});
$('#refreshPayroll')?.addEventListener('click',loadPayroll);
